    COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '个体工商户' THEN a.app_package END) AS app_tag_q_self_employed_cnt_730d,
    CASE WHEN COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) > 0 THEN CAST(COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '个体工商户' THEN a.app_package END) AS DOUBLE) / COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) ELSE 0 END AS app_tag_q_self_employed_ratio_730d,
    MAX(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '个体工商户' THEN 1 ELSE 0 END) AS app_tag_q_self_employed_flag_730d,
    SUM(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '个体工商户' THEN COALESCE(CAST(t.confidence AS DOUBLE), 0) ELSE 0 END) AS app_tag_q_self_employed_conf_wgt_730d,
    COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '网约车司机' THEN a.app_package END) AS app_tag_q_ride_hailing_cnt_730d,
    CASE WHEN COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) > 0 THEN CAST(COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '网约车司机' THEN a.app_package END) AS DOUBLE) / COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) ELSE 0 END AS app_tag_q_ride_hailing_ratio_730d,
    MAX(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '网约车司机' THEN 1 ELSE 0 END) AS app_tag_q_ride_hailing_flag_730d,
    SUM(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '网约车司机' THEN COALESCE(CAST(t.confidence AS DOUBLE), 0) ELSE 0 END) AS app_tag_q_ride_hailing_conf_wgt_730d,
    COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '优质客群' THEN a.app_package END) AS app_tag_q_good_customer_cnt_730d,
    CASE WHEN COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) > 0 THEN CAST(COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '优质客群' THEN a.app_package END) AS DOUBLE) / COUNT(DISTINCT CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 THEN a.app_package END) ELSE 0 END AS app_tag_q_good_customer_ratio_730d,
    MAX(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '优质客群' THEN 1 ELSE 0 END) AS app_tag_q_good_customer_flag_730d,
    SUM(CASE WHEN (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) >= 0 AND (unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime)) <= 63072000 AND t.quality_tag = '优质客群' THEN COALESCE(CAST(t.confidence AS DOUBLE), 0) ELSE 0 END) AS app_tag_q_good_customer_conf_wgt_730d
FROM d_dq.dfs_dq_fqz_base_final s
LEFT JOIN default.t_bd_credit_cust_app_info a
    ON s.cust_no = a.cust_no
    AND a.app_install_datetime IS NOT NULL
    AND unix_timestamp(a.app_install_datetime) <= unix_timestamp(s.close_datetime)
    AND unix_timestamp(s.close_datetime) - unix_timestamp(a.app_install_datetime) <= 63072000
LEFT JOIN d_dq.fqz_applist_tag_new t
    ON a.app_package = t.app_package
GROUP BY
    s.cust_no,
    s.apply_no,
    s.apply_result,
    s.close_datetime,
    s.cust_group_dq,
    s.fpd_k30,
    s.if_out_30d,
    s.if_out_60d,
    s.if_in_30d,
    s.if_in_60d,
    s.f001_decision
;
